-- ============================================================
-- Activity Notifications with LLM-generated creative messages
-- ============================================================
-- When a member completes an activity, all co-members (across
-- all shared clubs) receive a creative push notification
-- generated by Gemini Flash, with fallback templates.
--
-- Guardrails:
--   • Quiet hours: 7am–10pm IST only
--   • Per-user throttle: max 3 activity notifications/user/day
--   • 5-minute debounce: batch imports trigger at most one push
--   • Daily LLM budget: 100 calls/day (tracked in llm_usage)
--   • Internal-only: Edge Function verifies shared secret header
-- ============================================================

-- Daily LLM call counter (atomic budget enforcement)
CREATE TABLE IF NOT EXISTS public.llm_usage (
  date date PRIMARY KEY DEFAULT CURRENT_DATE,
  call_count integer NOT NULL DEFAULT 0
);

-- Notification log for throttle checks and observability
CREATE TABLE IF NOT EXISTS public.activity_notifications_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  activity_id uuid NOT NULL REFERENCES public.activities(id) ON DELETE CASCADE,
  source text NOT NULL CHECK (source IN ('gemini', 'fallback')),
  message text NOT NULL,
  recipients_count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS activity_notif_log_actor_day_idx
  ON public.activity_notifications_log (actor_user_id, created_at DESC);

-- Trigger function: fires on new activity, applies guardrails,
-- then calls the Edge Function via pg_net.
CREATE OR REPLACE FUNCTION public.trigger_activity_notification()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  ist_hour integer;
  daily_count integer;
  recent_count integer;
  webhook_url text;
BEGIN
  -- ── Quiet hours: only 7am–22pm IST ──
  ist_hour := EXTRACT(HOUR FROM (now() AT TIME ZONE 'Asia/Kolkata'));
  IF ist_hour < 7 OR ist_hour >= 22 THEN
    RETURN NEW;
  END IF;

  -- ── Per-user throttle: max 3 notifications/user/day ──
  SELECT COUNT(*) INTO daily_count
  FROM public.activity_notifications_log
  WHERE actor_user_id = NEW.user_id
    AND created_at >= (CURRENT_DATE AT TIME ZONE 'Asia/Kolkata');
  IF daily_count >= 3 THEN
    RETURN NEW;
  END IF;

  -- ── 5-minute debounce: skip if this user was notified recently ──
  --    (handles Health Connect bulk imports)
  SELECT COUNT(*) INTO recent_count
  FROM public.activity_notifications_log
  WHERE actor_user_id = NEW.user_id
    AND created_at >= now() - interval '5 minutes';
  IF recent_count > 0 THEN
    RETURN NEW;
  END IF;

  -- ── Fire the Edge Function ──
  webhook_url := current_setting('app.settings.supabase_url', true);
  IF webhook_url IS NULL THEN
    webhook_url := 'https://eswypmvrdgilkljytrxq.supabase.co';
  END IF;

  PERFORM net.http_post(
    url    := webhook_url || '/functions/v1/send-activity-notification',
    headers := jsonb_build_object(
      'Content-Type',      'application/json',
      'X-Internal-Secret', coalesce(
        current_setting('app.settings.internal_webhook_secret', true),
        'outpace-529db47ea1d8d5caeafb019e69ae1968715833f1aae0bb61b9cb39f96b44f0ab'
      )
    ),
    body   := jsonb_build_object(
      'activity_id',   NEW.id,
      'user_id',       NEW.user_id,
      'type',          NEW.type,
      'distance_m',    NEW.distance_m,
      'moving_time_s', NEW.moving_time_s,
      'elapsed_s',     NEW.elapsed_s,
      'calories',      NEW.calories,
      'started_at',    NEW.started_at
    )
  );

  RETURN NEW;
END; $$;

-- Atomic LLM budget counter — called from the Edge Function.
-- Returns TRUE if a call was claimed, FALSE if budget exhausted.
CREATE OR REPLACE FUNCTION public.increment_llm_usage(budget_limit integer)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  new_count integer;
BEGIN
  -- Upsert today's row and increment, but only if under budget
  INSERT INTO public.llm_usage (date, call_count)
  VALUES (CURRENT_DATE, 1)
  ON CONFLICT (date) DO UPDATE
    SET call_count = public.llm_usage.call_count + 1
    WHERE public.llm_usage.call_count < budget_limit
  RETURNING call_count INTO new_count;

  RETURN new_count IS NOT NULL;
END; $$;

-- Trigger: fires on every new activity inserted into the table.
-- GPS activities are inserted directly; imported activities arrive via upsert.
CREATE TRIGGER on_activity_created
  AFTER INSERT ON public.activities
  FOR EACH ROW
  EXECUTE FUNCTION public.trigger_activity_notification();
